/**
 * Validates all known fields present in a record using the registered validators.
 * @param {Object} record - An object whose keys correspond to validator names.
 * @returns {{ ok: boolean, results: Array }} An object indicating overall validity and per-field results.
 */
export function validateAll(record) {
  const results = [];
  for (const [key, validator] of Object.entries(VALIDATORS)) {
    if (record[key] === undefined) continue;
    results.push(validator(record[key]));
   }
  return { ok: results.every((r) => r.valid), results };
}

